+                if (val != expected) {
+                    throw new AssertionError(prefix + "expected [" + expected + "] but was [" + val + "]");
+                }
+            }
+            case SUM -> {
+                long expected = (BLOCK_LENGTH * (BLOCK_LENGTH - 1L)) * ((long) opCount) / 2;
